// Output 1 = temperatura, Output 2 = humedad
const temp = (Math.random()*15)+20; // 20.0 - 35.0
const hum = Math.floor(Math.random()*50)+30; // 30 - 79
const now = Date.now();
const msgTemp = { payload: Number(temp.toFixed(1)), topic: 'sensors/temperature', timestamp: now };
const msgHum = { payload: Number(hum), topic: 'sensors/humidity', timestamp: now };
return [msgTemp, msgHum];

// Cambia estos valores por los tuyos antes de la entrega
const NAME = 'TU_NOMBRE_COMPLETO';
const DOB = 'YYYY-MM-DD';
const payload = { name: NAME, fecha_nacimiento: DOB, timestamp: new Date().toISOString() };
const msg = { payload: JSON.stringify(payload), topic: 'sensors/info' };
// output 1 -> brokers (temp/hum mqtt out nodes no reciben esto)
return [msg, msg];

